def is_valid(s: str) -> bool:
    if len(s) % 2 == 1:
        return False
    stack = []
    mp = {')': '(', '}': '{', ']': '['}
    for ch in s:
        if ch not in mp:
            stack.append(ch)
        elif not stack or stack.pop() != mp[ch]:
            return False
    return not stack


def main():
    s = input().strip()
    print(str(is_valid(s)).lower())


if __name__ == "__main__":
    main()

def is_valid_ext(s: str):
    """返回 (是否有效, 首个错误下标或 -1)。"""
    stack = []
    mp = {')': '(', '}': '{', ']': '['}
    for i, ch in enumerate(s):
        if ch not in mp and ch not in mp.values():
            continue  # 忽略非括号字符
        if ch not in mp:
            stack.append((ch, i))
        else:
            if not stack or stack.pop()[0] != mp[ch]:
                return False, i
    return (len(stack) == 0), (stack[0][1] if stack else -1)


def main():
    s = input().strip()
    ok, pos = is_valid_ext(s)
    print(str(ok).lower())


if __name__ == "__main__":
    main()
